class Kopek:
  def __init__(self, isim):
    self.isim = isim # 'Benim ismim, dışarıdan gelen isimdir' demek

k = Kopek('Karabaş')
print(k.isim)

class Insan:
  def __init__(self, isim):
    self.isim = isim

  def selam_ver(self):
    print('Merhaba, benim adım ' + self.isim)

p1 = Insan('Veli')
p1.selam_ver()

class Insan:
  def __init__(kendi_kelimem, isim):
    kendi_kelimem.isim = isim

  def selam(kendi_kelimem):
    print('Selam ben ' + kendi_kelimem.isim)

p = Insan('Ali')
p.selam()

class BankaHesabi:
  def __init__(self, bakiye):
    self.bakiye = bakiye

  def para_yatir(self, miktar):
    self.bakiye += miktar

hesap = BankaHesabi(100)
hesap.para_yatir(50)
print('Yeni Bakiye:', hesap.bakiye)
